        __syncthreads();

        // Phase 2: TRMV - multiply by previous triangular factor
        for(rocblas_int i = tid; i < mm; i += tid_inc)
        {
            T temp = 0;
            for(rocblas_int j = i; j < mm; j++)
                temp += F[i + j * ldf] * work[j];
            Fx[i] = temp;
        }
        __syncthreads();
    }
}

